PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS user (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, emailVerified INTEGER NOT NULL, image TEXT, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS session (id TEXT PRIMARY KEY, expiresAt INTEGER NOT NULL, token TEXT NOT NULL UNIQUE, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL, ipAddress TEXT, userAgent TEXT, userId TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS session_user ON session(userId);
CREATE TABLE IF NOT EXISTS account (id TEXT PRIMARY KEY, accountId TEXT NOT NULL, providerId TEXT NOT NULL, userId TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, accessToken TEXT, refreshToken TEXT, idToken TEXT, accessTokenExpiresAt INTEGER, refreshTokenExpiresAt INTEGER, scope TEXT, password TEXT, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS identity_unique ON account(providerId,accountId);
CREATE INDEX IF NOT EXISTS account_user ON account(userId);
CREATE TABLE IF NOT EXISTS verification (id TEXT PRIMARY KEY, identifier TEXT NOT NULL, value TEXT NOT NULL, expiresAt INTEGER NOT NULL, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS verification_identifier ON verification(identifier);
CREATE TABLE IF NOT EXISTS participants (user_id TEXT PRIMARY KEY REFERENCES user(id) ON DELETE CASCADE, active INTEGER NOT NULL DEFAULT 0, generation INTEGER NOT NULL DEFAULT 0, version TEXT NOT NULL, granted_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS measurements (user_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, id TEXT NOT NULL, generation INTEGER NOT NULL, summary TEXT NOT NULL, digest TEXT NOT NULL, received_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, completed_at INTEGER, PRIMARY KEY(user_id,id,generation));
CREATE INDEX IF NOT EXISTS measurements_expiry ON measurements(expires_at);
CREATE UNIQUE INDEX IF NOT EXISTS measurements_identity ON measurements(user_id,id);
CREATE TABLE IF NOT EXISTS chunks (user_id TEXT NOT NULL, measurement_id TEXT NOT NULL, generation INTEGER NOT NULL, number INTEGER NOT NULL, digest TEXT NOT NULL, object_key TEXT NOT NULL UNIQUE, samples INTEGER NOT NULL, events INTEGER NOT NULL, PRIMARY KEY(user_id,measurement_id,generation,number), FOREIGN KEY(user_id,measurement_id,generation) REFERENCES measurements(user_id,id,generation) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS profile_snapshots (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, observed_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, gender TEXT, age_years INTEGER, residence_country TEXT, source TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS profile_expiry ON profile_snapshots(expires_at);
CREATE TABLE IF NOT EXISTS native_handoffs (id TEXT PRIMARY KEY, challenge TEXT NOT NULL, user_id TEXT, expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS deletion_jobs (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, prefix TEXT NOT NULL, created_at INTEGER NOT NULL, through_generation INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS deletion_tombstones (user_id TEXT PRIMARY KEY, deleted_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS rate_limits (key TEXT PRIMARY KEY, count INTEGER NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS measurement_receipts (user_id TEXT NOT NULL, measurement_id TEXT NOT NULL, first_received INTEGER NOT NULL, expires_at INTEGER NOT NULL, erased INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(user_id,measurement_id));
